<script setup>
import { ref } from 'vue'
import { useRouter } from 'vue-router'
import { ElMessage } from 'element-plus'
import { User, Lock, MostlyCloudy, Back, Connection, Camera, Position, UserFilled, Right } from '@element-plus/icons-vue'
import request from '@/utils/request'
const router=useRouter(),loginForm=ref({username:'',password:''})
const handleLogin=async()=>{const form=loginForm.value;if(!form.username||!form.password)return ElMessage.warning('用户名和密码不能为空');try{const res=await request.post('/api/login',{username:form.username,password:form.password});if(res.code!==200)return ElMessage.error(res.msg||'登录失败');if(res.data.role!=='ranger')return ElMessage.error('该账号不是护林员账号');localStorage.setItem('token',res.data.token);localStorage.setItem('currentUser',JSON.stringify(res.data));ElMessage.success('登录成功');router.push(window.innerWidth<=720?'/mobile':'/ranger')}catch(err){ElMessage.error('登录失败，请检查后端服务是否启动');console.error(err)}}
</script>
